import json
cs = json.load(open('csharp-out3.json'))
rs = json.load(open('rust-input3.json'))
def srcs(guide):
    out = {}
    def walk(c):
        for ins in c.get('Instructions', []) or []:
            out[(c['Name'], ins.get('Action'))] = ins.get('Source')
        for opt in c.get('Options', []) or []:
            walk(opt)
    for c in guide.get('thisMod', guide if isinstance(guide, list) else []):
        walk(c)
    return out
